class Solution:
    def findMinArrowShots(self, points: List[List[int]]) -> int:
        points.sort(key=lambda p: p[1])   # by right endpoint
        arrows = 0
        arrow_x = float('-inf')
        for start, end in points:
            if start > arrow_x:        # current arrow misses this balloon
                arrows += 1
                arrow_x = end          # shoot at its right edge
        return arrows

